/-- Fix [the amplitude](hyp:a) and [the probability law nu](hyp:nu). [Support and probability requirements of an amplitude prior](goal). -/
def AmplitudePrior (a : ℝ) (nu : Measure ℝ) : Prop :=
  IsProbabilityMeasure nu ∧ nu (Set.Icc (-a) a)ᶜ = 0

/-- Fix [the function f and the function g](hyp:f,g). [Eventual comparison of two real numerical sequences by fixed positive constants](goal). -/
def Comparable (f g : ℕ → ℝ) : Prop :=
  ∃ c C0 : ℝ, 0 < c ∧ c ≤ C0 ∧ ∀ᶠ k in Filter.atTop, c*g k ≤ f k ∧ f k ≤ C0*g k

/-- Fix [the probability law P](hyp:P). [Almost-sure consistency](goal). -/
def Consistency (P : Measure (FullRecord d)) : Prop :=
  P.real {w | outcome w = potential (arm w) w} = 1 -- @realizes Y(consistency)

/-- Fix [the probability law P](hyp:P). [Fair assignment conditional on both potential outcomes and the cell](goal). -/
def FairRandomization (P : Measure (FullRecord d)) : Prop :=
  ∀ (j : Fin d) (a y0 y1 : Bool),
    P.real {w | cell w = j ∧ arm w = a ∧ outcome0 w = y0 ∧ outcome1 w = y1} =
      (1/2 : ℝ) * P.real {w | cell w = j ∧ outcome0 w = y0 ∧ outcome1 w = y1}

/-- Fix [the probability law P](hyp:P). [Interior Bernoulli arm means](goal). -/
def InteriorMeans (P : Measure (FullRecord d)) : Prop :=
  ∀ a j, armMean P a j ∈ Set.Icc (1/4 : ℝ) (3/4) -- @realizes \mu(interior range)

/-- Fix [the order](hyp:k) and [the probability law nu0 and the probability law nu1](hyp:nu0,nu1). [Moment equality below the cancellation degree](goal). -/
def MatchingMoments (k : ℕ) (nu0 nu1 : Measure ℝ) : Prop :=
  ∀ q : ℕ, q < k → (∫ u, u^q ∂nu0) = ∫ u, u^q ∂nu1

/-- Fix [the local protocol Q](hyp:Q) and [the estimator T](hyp:T). [A decision is transcript-only when the public and analyst coins do not alter it](goal). -/
def TranscriptOnly (Q : LocalProtocol n α) (T : Estimator Q) : Prop :=
  ∃ f : ProtocolTranscript Q → ℝ, Measurable f ∧ ∀ w, T.1 w = f w.1

/-- Fix [the probability law P](hyp:P). [Uniform covariate marginal](goal). -/
def UniformCovariates (P : Measure (FullRecord d)) : Prop :=
  ∀ j, P.real {w | cell w = j} = (d : ℝ)⁻¹ -- @realizes X(uniform marginal)

/-- [The ancillary assignment has the parameter-independent fair law](goal). -/
-- @node: ancillaryBitLaw
def ancillaryBitLaw : Measure Bool := atomLaw (fun _ => (1/2 : ℝ))

/-- Fix [the probability law P](hyp:P), [the binary value a](hyp:a), and [the coordinate index](hyp:j). [Conditional cell mean, with division at zero cells interpreted by Lean](goal). -/
def armMean (P : Measure (FullRecord d)) (a : Bool) (j : Fin d) : ℝ :=
  P.real {w | cell w = j ∧ potential a w = true} / P.real {w | cell w = j}

/-- Fix [the function w](hyp:w). [Finite atomic law constructor](goal). -/
def atomLaw {α : Type} [Fintype α] [MeasurableSpace α] (w : α → ℝ) : Measure α :=
  ∑ a, ENNReal.ofReal (w a) • Measure.dirac a

/-- Fix [the probability law P](hyp:P). [Baseline mean](goal). -/
def baseline (P : Measure (FullRecord d)) : ℝ :=
  P.real {w | outcome w = true} -- @realizes B(E Y)

/-- Fix [the probability law P](hyp:P), [the privacy budget](hyp:eps), and [the function f](hyp:f). [Expectations on finite message blocks](goal). -/
def blockMean (P : Measure (FullRecord d)) (eps : ℝ) (f : (Fin m → Fin d → Bool) → ℝ) : ℝ :=
  ∫ z, f z ∂(vectorBlockLaw P eps m)

/-- Fix [the probability law P](hyp:P), [the privacy budget](hyp:eps), and [the function f](hyp:f). [Variance on finite message blocks](goal). -/
def blockVar (P : Measure (FullRecord d)) (eps : ℝ) (f : (Fin m → Fin d → Bool) → ℝ) : ℝ :=
  ∫ z, (f z - blockMean (m := m) P eps f)^2 ∂(vectorBlockLaw P eps m)

/-- Fix [the sample size and the dimension](hyp:n,d). [Canonical iid scheme, displaying non-vacuity of the sampling atoms](goal). -/
def canonicalScheme (n d : ℕ) : SamplingScheme n d :=
  fun _ _ lam P => (Measure.pi (fun _ : Fin n => observedLaw P)).prod (lam.prod uniform01)

/-- Fix [the dimension](hyp:d). [The complete law class, including ambient probability typing](goal). -/
def causalClass (d : ℕ) : Set (Measure (FullRecord d)) :=
  {P | IsProbabilityMeasure P ∧ CausalModel P} -- @realizes \mathcal V_d(full causal law class)

/-- Fix [the privacy budget](hyp:eps), [the natural-number parameter D](hyp:D), [the coordinate index](hyp:j), and [the function w](hyp:w). [The hybrid rule applied to a single combined scaled column](goal). -/
-- @node: combinedHybridStatistic
def combinedHybridStatistic (eps : ℝ) (D : ℕ) (j : Fin d)
    (w : Fin (m+m) → ℝ) : ℝ :=
  let T := 4 * Real.sqrt (sigmaSquared d m eps) * Real.sqrt (logDim d)
  let pilot := (m : ℝ)⁻¹ * ∑ i : Fin m, w (Fin.castAdd m i)
  let evaluation := (m : ℝ)⁻¹ * ∑ i : Fin m, w (Fin.natAdd m i)
  let poly := ∑ v ∈ Finset.range (D+1), (chebyshevAbsPoly D).coeff v *
    (2*T)^((1 : ℤ) - (v : ℤ)) *
      privateMoment (fun i : Fin m => fun _ : Fin d => w (Fin.natAdd m i)) v j
  if |pilot| ≤ T then poly
  else (if 0 < pilot then 1 else if pilot < 0 then -1 else 0) * evaluation

/-- Fix [the probability law P](hyp:P) and [the coordinate index](hyp:j). [Cellwise contrast](goal). -/
def contrast (P : Measure (FullRecord d)) (j : Fin d) : ℝ :=
  armMean P true j - armMean P false j -- @realizes \tau(μ1−μ0)

/-- Fix [the dimension](hyp:d) and [the privacy budget](hyp:eps). [Coordinate privacy derivative scale](goal). -/
def derivativeScale (d : ℕ) (eps : ℝ) : ℝ :=
  (Real.exp eps - 1)/(2*d) -- @realizes \beta((exp ε−1)/(2d))

/-- Fix [the sample size and the dimension](hyp:n,d) and [the privacy budget](hyp:eps). [Attaining Borel estimator packaged without any unproved definitional payload](goal). -/
def frontierEstimator (n d : ℕ) (eps : ℝ) : Estimator (frontierProtocol n d eps) :=
  ⟨frontierEstimate n d eps, frontierEstimate_measurable n d eps⟩

/-- Fix [the sample size and the dimension](hyp:n,d), [the privacy budget](hyp:eps), and [the protocol decision](hyp:w). [Upper endpoint of the concrete connected interval](goal). -/
def frontierHi (n d : ℕ) (eps : ℝ) (w : DecisionSpace (frontierProtocol n d eps)) : ℝ :=
  min (3/4) (frontierEstimate n d eps w + frontierHonestyRadius n d eps)

/-- Fix [the sample size and the dimension](hyp:n,d) and [the privacy budget](hyp:eps). [The fixed honesty radius prescribed for every branch, including n=2](goal). -/
def frontierHonestyRadius (n d : ℕ) (eps : ℝ) : ℝ :=
  Real.sqrt ((10 : ℝ)^17 * rho (n * eps^2) d)

/-- Fix [the sample size and the dimension](hyp:n,d), [the privacy budget](hyp:eps), and [the protocol decision](hyp:w). [Lower endpoint with the prescribed fixed honesty radius](goal). -/
def frontierLo (n d : ℕ) (eps : ℝ) (w : DecisionSpace (frontierProtocol n d eps)) : ℝ :=
  max (1/4) (frontierEstimate n d eps w - frontierHonestyRadius n d eps)

