/-- Fix [the protocol transcript](hyp:z) and [the participant index](hyp:i). [Safe extraction from a finite transcript, returning a fixed unused message past the horizon](goal). -/
def messageAt (z : ProtocolTranscript (frontierProtocol n d eps)) (i : ℕ) : FrontierMessage d :=
  if hi : i < n then z ⟨i,hi⟩ else (false,fun _ => false)

/-- Fix [the sampling scheme S](hyp:S), [the protocol-class label](hyp:C), and [the privacy budget](hyp:eps). [Mechanism-optimal scalar causal risk](goal). -/
def minimaxRisk (S : SamplingScheme n d) (C : ProtocolClassLabel) (eps : ℝ) : ℝ≥0∞ :=
  riskValue (causalClass d) value (decisionLaw S) C eps

/-- Fix [the observed participant record](hyp:o). [Signed observation](goal). -/
def obsSign (o : ObsRecord d) : ℝ :=
  signVal o.2.1 * signVal o.2.2 -- @realizes S((2A−1)(2Y−1))

/-- Fix [the full participant record](hyp:w). [Observation projection](goal). -/
def observe (w : FullRecord d) : ObsRecord d :=
  (cell w, arm w, outcome w) -- @realizes O((X,A,Y))

/-- Fix [the probability law P](hyp:P). [Observed marginal](goal). -/
def observedLaw (P : Measure (FullRecord d)) : Measure (ObsRecord d) :=
  P.map observe -- @realizes P_O(observed marginal)

/-- Fix [the dimension](hyp:d). [The closed paired contrast family](goal). -/
def pairedFamily (d : ℕ) : Set (Measure (PairedSymbol d)) :=
  pairedLaw '' parameterCube d -- @realizes \mathcal P_d^{\mathrm{pair}}(image of contrast cube)

/-- Fix [the function theta](hyp:theta). [Paired signed law](goal). -/
def pairedLaw (theta : Fin d → ℝ) : Measure (PairedSymbol d) :=
  atomLaw (fun v => (1 + signVal v.2 * theta v.1) / (2 * d)) -- @realizes P_\theta((1+sθj)/(2d))

/-- Fix [the dimension](hyp:d). [Public uniform paired law](goal). -/
def pairedUniform (d : ℕ) : Measure (PairedSymbol d) :=
  pairedLaw (fun _ => 0) -- @realizes \mathsf U_{2d}(uniform paired law)

/-- Fix [the dimension](hyp:d). [Parameter cube](goal). -/
def parameterCube (d : ℕ) : Set (Fin d → ℝ) :=
  {theta | ∀ j, theta j ∈ Set.Icc (-(1/2 : ℝ)) (1/2)} -- @realizes \theta(cube)

/-- Fix [the binary value a](hyp:a) and [the full participant record](hyp:w). [Arm-indexed potential outcome](goal). -/
def potential (a : Bool) (w : FullRecord d) : Bool :=
  if a then outcome1 w else outcome0 w

/-- Fix [the function W](hyp:W), [the order](hyp:k), and [the coordinate index](hyp:j). [Distinct-person unbiased power statistic including degree zero](goal). -/
def privateMoment (W : Fin m → Fin d → ℝ) (k : ℕ) (j : Fin d) : ℝ :=
  (Nat.choose m k : ℝ)⁻¹ * ∑ J ∈ Finset.univ.powersetCard k, ∏ i ∈ J, W i j

/-- Fix [the dimension](hyp:d) and [the probability law nu](hyp:nu). [Product prior, independent of the public seed](goal). -/
def productPrior (d : ℕ) (nu : Measure ℝ) : Measure (Fin d → ℝ) :=
  Measure.pi (fun _ => nu) -- @realizes \Pi_0(ν0 tensor d) @realizes \Pi_1(ν1 tensor d)

/-- Fix [the protocol-class label](hyp:C), [the sample size and the dimension](hyp:n,d), and [the privacy budget](hyp:eps). [Connected honest-length rate](goal). -/
def rateH (C : ProtocolClassLabel) (n d : ℕ) (eps : ℝ) : ℝ :=
  Real.sqrt (rateR C n d eps) -- @realizes h_{\mathcal C}(sqrt risk rate)

/-- Fix [the protocol-class label](hyp:_C), [the sample size and the dimension](hyp:n,d), and [the privacy budget](hyp:eps). [Class-independent squared-error rate](goal). -/
def rateR (_C : ProtocolClassLabel) (n d : ℕ) (eps : ℝ) : ℝ :=
  rho (n * eps^2) d -- @realizes r_{\mathcal C}(piecewise rho)

/-- Fix [the parameter v](hyp:v) and [the binary value a](hyp:a). [Reconstruct the original observation using an ancillary assignment bit](goal). -/
def recoverObs (v : PairedSymbol d) (a : Bool) : ObsRecord d :=
  (v.1,a,if v.2 then a else !a)

/-- Fix [the real parameter t](hyp:t) and [the dimension](hyp:d). [Evaluated finite-resource rate](goal). -/
def rho (t : ℝ) (d : ℕ) : ℝ :=
  let L := logDim d
  if (d : ℝ)^2 * L ≤ t then (d : ℝ)^2 / (t * L)
  else min 1 (Real.log (Real.exp 1 + (d : ℝ)^2 * L / t) / L)^2

/-- Fix [the privacy budget](hyp:eps), [the coordinate index](hyp:j), and [the function z](hyp:z). [Mean of one scaled column](goal). -/
def scaledColumnMean (eps : ℝ) (j : Fin d) (z : Fin m → Fin d → Bool) : ℝ :=
  (m : ℝ)⁻¹ * ∑ i, scaledMessages eps z i j

/-- Fix [the privacy budget](hyp:eps), [the function z](hyp:z), [the participant index](hyp:i), and [the coordinate index](hyp:j). [Scaled message matrix](goal). -/
def scaledMessages (eps : ℝ) (z : Fin m → Fin d → Bool) (i : Fin m) (j : Fin d) : ℝ :=
  noiseScale d eps * signVal (z i j) -- @realizes W(b Z_ij)

/-- Fix [the probability law P](hyp:P) and [the coordinate index](hyp:j). [Conditional signed cell mean](goal). -/
def signedCellMean (P : Measure (FullRecord d)) (j : Fin d) : ℝ :=
  (∫ w, if cell w = j then obsSign (observe w) else 0 ∂P) / P.real {w | cell w = j}

/-- Fix [the function theta](hyp:theta). [Signed average absolute norm](goal). -/
def signedNorm (theta : Fin d → ℝ) : ℝ :=
  (d : ℝ)⁻¹ * ∑ j, |theta j| -- @realizes F(mean absolute contrast)

/-- Fix [the dimension](hyp:d). [All probability laws on the finite paired alphabet](goal). -/
def simplexModel (d : ℕ) : Set (Measure (PairedSymbol d)) :=
  {p | IsProbabilityMeasure p}

/-- Fix [the probability law L](hyp:L), [the estimator T](hyp:T), and [the real parameter v](hyp:v). [Extended nonnegative squared-error expectation; infinite risks stay infinite](goal). -/
def squaredRisk (L : Measure (DecisionSpace Q)) (T : Estimator Q) (v : ℝ) : ℝ≥0∞ :=
  ∫⁻ w, ENNReal.ofReal ((T.1 w - v)^2) ∂L

/-- Fix [the probability law p](hyp:p). [Scalar total variation from the public uniform law on the paired alphabet](goal). -/
def tvFromUniform (p : Measure (PairedSymbol d)) : ℝ :=
  (1/2 : ℝ) * ∑ v : PairedSymbol d, |p.real {v} - 1/(2*d)|

/-- Fix [the sample size and the dimension](hyp:n,d) and [the privacy budget](hyp:eps). [The measurable transcript-only paired estimator](goal). -/
def tvFrontierEstimator (n d : ℕ) (eps : ℝ) : Estimator (tvFrontierProtocol n d eps) :=
  ⟨tvFrontierEstimate n d eps, tvFrontierEstimate_measurable n d eps⟩

/-- Fix [the sample size and the dimension](hyp:n,d), [the privacy budget](hyp:eps), and [the protocol transcript](hyp:z). [Embed paired vector messages in the common private polynomial computation](goal). -/
def tvToNormTranscript (n d : ℕ) (eps : ℝ)
    (z : ProtocolTranscript (tvFrontierProtocol n d eps)) :
    ProtocolTranscript (frontierProtocol n d eps) :=
  fun i =>
    let m0 := (frontierDesign n d eps).resources.m0
    if i.val < m0 then (false,fun _ => false)
    else if h : i.val - m0 < n then (false,z ⟨i.val-m0,h⟩)
    else (false,fun _ => false)

/-- Fix [the sample size](hyp:n) and [the privacy budget](hyp:eps). [The deterministic radius in the two-cell calibration roadmap](goal). -/
-- @node: twoCellRadius
def twoCellRadius (n : ℕ) (eps : ℝ) : ℝ := Real.sqrt (10000 / ((n : ℝ) * eps ^ 2))

/-- Fix [the probability law P](hyp:P). [First-best population value](goal). -/
def value (P : Measure (FullRecord d)) : ℝ :=
  (d : ℝ)⁻¹ * ∑ j, max (armMean P false j) (armMean P true j) -- @realizes V(mean arm maximum)

/-- Fix [the dimension](hyp:d) and [the privacy budget](hyp:eps). [Explicit finite signed-vector channel](goal). -/
def vectorKernel (d : ℕ) (eps : ℝ) : Kernel (ObsRecord d) (Fin d → Bool) :=
  ⟨fun o => atomLaw (vectorMass eps o), measurable_of_countable _⟩

/-- Fix [the privacy budget](hyp:eps), [the observed participant record](hyp:o), and [the function z](hyp:z). [Signed-vector atom weight](goal). -/
def vectorMass (eps : ℝ) (o : ObsRecord d) (z : Fin d → Bool) : ℝ :=
  (2 : ℝ)^(-(d : ℤ)) * (1 + privacyDelta eps * obsSign o * signVal (z o.1))

/-- Fix [the probability law P](hyp:P) and [the privacy budget](hyp:eps). [One signed-vector message law](goal). -/
def vectorMessageLaw (P : Measure (FullRecord d)) (eps : ℝ) : Measure (Fin d → Bool) :=
  (observedLaw P).bind (vectorKernel d eps)

/-- Fix [the privacy budget](hyp:eps) and [the observed participant record](hyp:o). [Direct product sampler: distinguished coordinate has mean δS; others are fair](goal). -/
def vectorSamplerLaw (eps : ℝ) (o : ObsRecord d) : Measure (Fin d → Bool) :=
  Measure.pi (fun j => atomLaw (fun s : Bool =>
    if j = o.1 then (1 + privacyDelta eps * obsSign o * signVal s)/2 else 1/2))
